import React, { useState, useEffect } from 'react';
import emailjs from 'emailjs-com';
import ReCAPTCHA from "react-google-recaptcha";

export default function ContactForm() {
  const [form, setForm] = useState({ reason: "", email: "", message: "", phone: "", linkedin: ""});
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [userActions, setUserActions] = useState([]);
  const [loading, setLoading] = useState(false);
  const [captchaToken, setCaptchaToken] = useState(null); // ✅ new state

  const handleChange = e => setForm({...form, [e.target.name]: e.target.value});
  const validateEmail = email => /\S+@\S+\.\S+/.test(email);

  // Track user actions
  useEffect(() => {
    const handleMouseMove = e => {
      setUserActions(prev => [...prev, `Mouse at (${e.clientX}, ${e.clientY})`]);
    };
    const handleScroll = () => {
      setUserActions(prev => [...prev, `Scrolled to Y=${window.scrollY}`]);
    };
    const startTime = Date.now();

    window.addEventListener("mousemove", handleMouseMove);
    window.addEventListener("scroll", handleScroll);

    return () => {
      const duration = Math.round((Date.now() - startTime) / 1000);
      setUserActions(prev => [...prev, `Time spent: ${duration} seconds`]);
      window.removeEventListener("mousemove", handleMouseMove);
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);

  const handleSubmit = e => {
    e.preventDefault();
    if (!validateEmail(form.email)) {
      setError("Please enter a valid email.");
      return;
    }
    if (!captchaToken) {
      setError("Please complete the captcha.");
      return;
    }
    setError("");
    setLoading(true);

    emailjs.send(
      "service_c8jpnu9",
      "template_9xubazc",
      {
        reason: form.reason,
        email: form.email,
        message: form.message,
        phone: form.phone,
        linkedin: form.linkedin,
        actions: [...userActions, `Captcha token: ${captchaToken}`].join("\n")
      },
      "qPlYyGFrLbI8p1Eym"
    ).then(() => {
      setSuccess("Message sent successfully!");
      setForm({ reason: "", email: "", message: "", phone: "", linkedin: "" });
      setUserActions([]);
      setCaptchaToken(null);
    }).catch(err => setError("Failed to send message."))
      .finally(() => setLoading(false));
  };

  return (
    <section>
      <h2>Contact Me</h2>
      <form onSubmit={handleSubmit}>
        <label>
          Reason:
          <select name="reason" value={form.reason} onChange={handleChange}>
            <option value="">Select...</option>
            <option value="Job Opportunity">Job Opportunity</option>
            <option value="Collaboration">Collaboration</option>
            <option value="Other">Other</option>
          </select>
        </label>
        <label>
          Email:
          <input type="email" name="email" value={form.email} onChange={handleChange} required />
        </label>
        <label>
          Message:
          <textarea name="message" value={form.message} onChange={handleChange} required />
        </label>
        <label>
          Phone:
          <input type="tel" name="phone" value={form.phone} onChange={handleChange} placeholder='Optional' />
        </label>
        <label>
          LinkedIn:
          <input type="url" name="linkedin" value={form.linkedin} onChange={handleChange} placeholder='Optional' />
        </label>

        {/* Captcha inside the form */}
        <ReCAPTCHA
          sitekey="6LeqMIcsAAAAAEQZqalP9FeVLEDbR7Z11OSvy3Jl"
          onChange={(value) => setCaptchaToken(value)}
        />

        {error && <p style={{color:"red"}}>{error}</p>}
        {success && <p style={{color:"green"}}>{success}</p>}
        {loading && <p style={{color:"blue"}}>Sending...</p>}
        <button type="submit" disabled={loading}>
          {loading ? "Sending..." : "Send"}
        </button>
      </form>
    </section>
  );
}
