import React from 'react';


const projects = [
  { name: "focusNexus", link: "https://github.com/RandomSE/focusNexus", description: "Gamified productivity app with a focus on accessibility" },
  { name: "Multi language task manager API", link: "https://github.com/RandomSE/Multi-Language-Task-Manager-API", description: "Simple task manager API in multiple languages" },
  { name: "Pathwise", link: "https://github.com/RandomSE/Pathwise", description: "Planned to be used for behavioral analysis and visualization, as well as for new intersections before they are made to check safety for pedestrians." }
];

export default function Projects() {
  return (
    <section>
      <h2>Projects</h2>
      <ul>
        {projects.map((p, i) => (
          <li key={i}>
            <a href={p.link} target="_blank" rel="noopener noreferrer">{p.name}</a> – {p.description}
          </li>
        ))}
      </ul>
    </section>
  );
}
