import React from 'react';
import './App.css';


export default function AboutMe() {
  return (
    <section>
      <h2>About Me</h2>
      <img src={`${process.env.PUBLIC_URL}/profile.jpg`} alt="Joshua" style={{width: 281, height: 408}} />
      <p>Hi, I'm Joshua. I'm a backend software engineer focused on building reliable systems and improving the infrastructure that supports them.
       <br />
       My primary stack is modern Java with Spring, cloud platforms like AWS, and CI/CD pipelines that enable fast and safe deployments. 
       <br />
       I enjoy working on the parts of a system that make everything else run better, from optimizing build pipelines and improving observability, 
       <br />
       to upgrading frameworks and reducing technical risk before it becomes a problem. I also have experience with frontend development and am always eager to learn new technologies.
       <br />
        I also enjoy camembert.
      </p>
    </section>
  );
}
